// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {VaultAdapter} from "../src/VaultAdapter.sol";

contract InvMutTest is Test {
    VaultAdapter c;

    function setUp() public {
        c = new VaultAdapter();
    }

    function testFuzz_property(address admin1, address admin2) public {
        vm.assume(admin1 != address(0));
        vm.assume(admin2 != address(0));

        // Deploy the implementation behind a minimal ERC1967 proxy so
        // initializers are live (direct deployment disables them).
        MinimalProxy proxy = new MinimalProxy(address(c));

        // First initialize through the proxy must succeed in both versions.
        (bool ok1,) = address(proxy).call(abi.encodeWithSelector(VaultAdapter.initialize.selector, admin1));
        assertTrue(ok1, "first initialize should succeed via proxy");

        // A second initialize must revert (initializer is one-shot).
        (bool ok2,) = address(proxy).call(abi.encodeWithSelector(VaultAdapter.initialize.selector, admin2));
        assertTrue(!ok2, "second initialize must revert");
    }
}

contract MinimalProxy {
    bytes32 private constant IMPL_SLOT =
        0x360894a13ba1a3210667c828492db98dca3e2076cc3735a920a3ca505d382bbc;

    constructor(address impl) {
        assembly {
            sstore(IMPL_SLOT, impl)
        }
    }

    fallback() external payable {
        assembly {
            let impl := sload(IMPL_SLOT)
            calldatacopy(0, 0, calldatasize())
            let result := delegatecall(gas(), impl, 0, calldatasize(), 0, 0)
            returndatacopy(0, 0, returndatasize())
            switch result
            case 0 { revert(0, returndatasize()) }
            default { return(0, returndatasize()) }
        }
    }
}
